The [CODE] DateRangeFilter [/CODE] provided by [CODE] django-filter [/CODE] allows you to filter across common date ranges like "today", "the past week", "last month", etc. It does not allow you to filter a queryset down to a specific date. You should be able to do this with a custom filter though. [CODE] from django_filters.filters import DateFilter

class WithinDateFilter(DateFilter):

    def filter(self, qs, value):
        from datetime import timedelta

        if value:
            date_value = value.replace(hour=0, minute=0, second=0)

            filter_lookups = {
                "%s__range" % (self.name, ): (
                    value,
                    value + timedelta(days=1),
                ),
            }

            qs = qs.filter(**filter_lookups)

