    return str.join("", (chr(random.randrange(97, 123))
                         for i in range(random.randrange(3, 16))))

class A(object):
    def __init__(self):
        self.x = rand_str()
        self.y = rand_str()
    def __hash__(self):
        return hash(self.x)
    def __eq__(self, other):
        return self.x == other.x
 [/CODE] The amount of memory used by a set of 1,000,000 instances of this class [CODE] random.seed(42)
s = set(A() for i in xrange(1000000))
 [/CODE] is on my machine 240 MB.  If I add [CODE]     __slots__ = ("x", "y")
 [/CODE] to the class, this goes down to 112 MB.  If I store the same data in a dictionary [CODE] def key_value():
    a = A()
    return a.x, a

random.seed(42)
d = dict(key_value() for i in xrange(1000000))
