def writeToFile(conn):
    with open(filename, "a") as f: # Just leave the file open for performance reasons.
        while True:
            currentPos = conn.recv()        
            f.write("{}\n".format(currentPos))

if __name__ == "__main__":
    parent_conn, child_conn = mp.Pipe()
